from rdkit import Chem

smi = "COc1ccc(O[C@@H]2[C@@H](C(=O)N3CCC[C@@H]3C5=O)N(C(=O)[C@@H](CC(C)C)NC(=O)[C@@H](N(C)C)[C@@H](C)CC)CC2)cc1/C=C\\N5"
m = Chem.MolFromSmiles(smi)
Chem.AssignStereochemistry(m, cleanIt=True, force=True)
for a in m.GetAtoms():
    if a.HasProp('_CIPCode'):
        print(a.GetIdx(), a.GetSymbol(), a.getProp('_CIPCode'), [n.GetIdx() for n in a.GetNeighbors()])
for b in m.GetBonds():
    if b.GetBondType()==Chem.BondType.DOUBLE and b.GetStereo()!=Chem.BondStereo.STEREONONE:
        print("DB", b.GetBeginAtomIdx(), b.GetEndAtomIdx(), b.GetStereo())
print("heavy atoms:", m.GetNumAtoms())
# identify centers by neighbor environment for reference
for a in m.GetAtoms():
    if a.HasProp('_ChiralityPossible') and not a.HasProp('_CIPCode'):
        print("possible:", a.GetIdx(), a.GetSymbol())
